// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { facetCountQuery } from "../../../main/frontend/graph-explorer/facet-queries.ts";

test("repository counts follow the graph scope and the preferred label language", () => {
  const named = facetCountQuery(["urn:a"], "urn:p", "urn:ex:graph", ["nb", "en"]);
  assert.match(named, /GRAPH <urn:ex:graph> \{ \?source <urn:p> \?value \. \}/);
  assert.match(named, /LANGMATCHES\(LANG\(\?valueLabel\), "nb"\)/);
  const plain = facetCountQuery(["urn:a"], "urn:p");
  assert.match(plain, /\?source <urn:p> \?value \./);
  assert.match(plain, /"en"/);
  assert.doesNotMatch(facetCountQuery(["urn:a"], "urn:p", "default", ['en") || true || ("']), /true \|\|/);
});
